tar -tzf "$PAYLOAD_FILE" >/dev/null || { echo 'Installer payload archive validation failed.' >&2; exit 1; }
tar -xzf "$PAYLOAD_FILE" -C "$TMPDIR"
chmod 0755 "$TMPDIR/veloraos-1.10.27/installer/veloraos-install.sh"
/bin/bash "$TMPDIR/veloraos-1.10.27/installer/veloraos-install.sh" "$@"
exit 1
